-- Registry row for the 2026-09-26 portfolio-exposure amendment (migration 44), generated by
-- python3 tools/court/build_rules.py --upsert portfolio-exposure
insert into public.desk_rules (rule_id, title, purpose, mechanism, owner_paths, status, verdict, ruling_summary, growth_cost, ruin_risk_reduction, statistics_note, gaming_analysis, interactions, needs_david, ruling_file, ruling_date, next_review_date) values
  ('portfolio-exposure', 'Portfolio exposure: open risk <= 10% of book (gap-prone lots at full notional)', 'Per-entry caps don''t bound total or correlated exposure across open lots, and an invalidation line doesn''t bound a lot that can gap straight through it.', '`private.open_risk_lots()` (per lot, `public.v_exposure_lots`) summed by `private.steward_open_risk` (`public.v_exposure_usage`), in the book unit, `risk_basis` per book. QUANTANAMO equities `to_invalidation`: qty x max(mark - invalidation_price, 0) (no invalidation: qty x mark; unmarked: 0, flagged). ODDSBORNE binaries and BANDIT memes `full_notional`: every open binary at price x contracts (mark, else average cost) and every meme lot at its full cost basis (qty x average cost, else qty x mark). Budget 10% of book. Guidance sizes a new entry to fit: min(requested, max_stake, cash, headroom / risk fraction), where the fraction is 1 for full_notional books and (entry - invalidation) / entry for equities (1 without p_entry_price); no headroom -> `exposure_cap`. Guidance, v_exposure_usage and the v_ledger_watchdog `exposure` summary carry `risk_basis`.', array['supabase/schemas/41_court_decisions.sql', 'supabase/schemas/44_exposure_gap_full_notional.sql']::text[], 'in_force', 'amend', 'Enact option (b) at R = 10% (migration 41; decided 2026-09-26 by the parent agent under David''s delegation). Amended the same day (migration 44): ODDSBORNE binaries and BANDIT memes count at full notional, equities keep to-invalidation. After QUANTANAMO raised its lines it is at 6.4% (was 11.9%, blocked); ODDSBORNE and BANDIT have no open lots (0%). Amendment: Open risk <= 10% of book per steward, gap-prone lots (binaries, memes) at full notional and equities to invalidation; guidance sizes down or blocks and reports `risk_basis`.', 'Caps stacking; at a 10% invalidation distance equities still allow ~100% of book in positions. BANDIT holds about 1.5 starters at once (0.180 SOL budget), ODDSBORNE about 10% of book in open tickets.', 'Bounds the loss if every open lot hits its invalidation at once (equities) or goes to zero (binaries, memes) to 10% of book.', 'Needs a correlation estimate by theme; with n this small, use theme membership as the proxy. For binaries and memes the loss distribution is bimodal (full loss or not), so the right risk unit is the notional, not a distance to a line.', 'Without it, a steward can stack correlated starters across several theses. To-invalidation on a gap-prone lot rewards writing a tight line the venue can''t honor; full notional removes that lever.', 'cash-only-no-margin, required-invalidation, edge-max-stake, starter-stake.', false, 'docs/rules/portfolio-exposure.md', '2026-09-26'::date, '2026-10-26'::date)
on conflict (rule_id) do update set title = excluded.title, purpose = excluded.purpose, mechanism = excluded.mechanism, owner_paths = excluded.owner_paths, status = excluded.status, verdict = excluded.verdict, ruling_summary = excluded.ruling_summary, growth_cost = excluded.growth_cost, ruin_risk_reduction = excluded.ruin_risk_reduction, statistics_note = excluded.statistics_note, gaming_analysis = excluded.gaming_analysis, interactions = excluded.interactions, needs_david = excluded.needs_david, ruling_file = excluded.ruling_file, ruling_date = excluded.ruling_date, next_review_date = excluded.next_review_date, updated_at = now();
